function buildLevel(){
  blocks = [];
  const cols = 12;
  const rows = Math.min(4 + level, 8);
  const margin = 36, top = 70, gap = 5;
  const bw = (W - margin*2 - gap*(cols-1)) / cols;
  const bh = 22;
  for(let r = 0; r < rows; r++){
    for(let c = 0; c < cols; c++){
      let hp = 1;
      if(level >= 2 && r === 0 && c % 2 === 0) hp = 2;
      if(level >= 4 && r === 1 && (c % 4 === 1)) hp = 2;
      blocks.push({ x: margin + c*(bw+gap), y: top + r*(bh+gap), w: bw, h: bh, hp, max: hp, hue: r });
    }
  }
  paddle.w = Math.max(76, 112 - (level-1)*6);
  ball.speed = 330 + (level-1)*25;
  ball.stuck = true;
  ball.vx = 0; ball.vy = 0;
  ball.x = paddle.x + paddle.w/2;
  ball.y = paddle.y - ball.r - 1;
}
